/* Lo que la medición de colisión (A7) tiene que dar sobre el fixture de arriba,
   calculado A MANO desde ENTIDADES_HIST(_IDENTIDAD): por entidad, colisión =
   ofertas con i % 3 === 0 SI son ≥ 2; control = el resto. Pooled. */
function colisionEsperadaDelFixture() {
  let col = 0, ctrl = 0, sumCol = 0, esperado = 0, ents = 0;
  /* Se agrupa por la MISMA clave canónica del índice: la entidad «con guion» y
     «sin guion» del fixture de identidad son UNA entidad para el índice (fue el
     defecto de ago 2026), y sus dos procesos «i = 0» cierran el mismo día. */
  const { claveCanonica } = require("../lib/indice_competencia.js");
  const porClave = new Map();
  for (const e of [...ENTIDADES_HIST, ...ENTIDADES_HIST_IDENTIDAD]) {
    const k = claveCanonica(e.entidad);
    const g = porClave.get(k) || { c: [], r: [] };
    e.ofertas.forEach((o, i) => (i % 3 === 0 ? g.c : g.r).push(o));
    porClave.set(k, g);
  }
  for (const { c, r } of porClave.values()) {
    if (c.length < 2 || !r.length) continue;
    ents++;
    col += c.length; ctrl += r.length;
    const sc = c.reduce((a, b) => a + b, 0), mr = r.reduce((a, b) => a + b, 0) / r.length;
    sumCol += sc; esperado += c.length * mr;
  }
  return { entidades: ents, procesos_colision: col, procesos_control: ctrl, cociente: Math.round((esperado / sumCol) * 100) / 100 };
}

/* ════════════════ mock Socrata (SoQL mínimo) ════════════════ */
function crearMockSocrata() {
  let dataset = [];
  /* SEGUNDO dataset, servido por PATH: el PAA vive en `9sue-ezhx` y el de
     siempre en `p6dx-8zbt`. El mock ignoraba la ruta, así que sin esto la
     consulta del PAA habría recibido el corpus de SECOP II y la prueba habría
     pasado midiendo otra cosa. */
  let datasetPaa = [];
  /* TERCER dataset, también por PATH: `hgi6-6wh3` (proponentes por proceso).
     lib/proponentes consulta AGRUPADO (`$group`, `count(*)`, `max(...)`,
     `count(distinct …)`) y filtra con `id_procedimiento in ('a','b')`: el
     mock lo resuelve aparte, con lo justo para que la consulta real —la misma
     URL que se manda a Socrata— se pueda ejercitar sin red. */
  let datasetProponentes = [];
  /* CUARTO dataset por PATH: `jbjy-vk9h` (contratos electrónicos), que
     lib/ejecucion consulta con igualdades y `>=` sobre fecha_de_firma: cae en
     la rama genérica del mock. */
  let datasetContratos = [];
  /* QUINTO y SEXTO por PATH: `iaeu-rcn6` (SIRI) y `4n4q-k399` (multas SECOP I),
     que lib/socio consulta con `starts_with(campo,'…')`: rama genérica. */
  let datasetSiri = [];
  let datasetMultas = [];
  let contadorPeticiones = 0;
  let inyectarFallos = true;

  const responderProponentes = (q, res) => {
    let filas = datasetProponentes.slice();
    const mIn = /^\s*(\S+)\s+in\s*\((.*)\)\s*$/i.exec(String(q.$where || ""));
    if (q.$where && !mIn) { res.writeHead(400); return res.end(JSON.stringify({ error: true, message: `mock hgi6: where no soportado: ${q.$where}` })); }
    if (mIn) {
      const ids = new Set(mIn[2].split(",").map((x) => x.trim().replace(/^'|'$/g, "").replace(/''/g, "'")));
      filas = filas.filter((f) => ids.has(String(f[mIn[1]])));
    }
    const sel = String(q.$select || "");
    res.writeHead(200, { "Content-Type": "application/json" });
    if (/^count\(distinct (\S+)\)/i.test(sel)) {
      const campo = /^count\(distinct (\S+)\)/i.exec(sel)[1];
      return res.end(JSON.stringify([{ procesos: String(new Set(filas.map((f) => f[campo])).size) }]));
    }
    if (q.$group) {
      const claves = q.$group.split(",").map((x) => x.trim());
      const grupos = new Map();
      for (const f of filas) {
        const k = claves.map((c) => String(f[c] ?? "")).join("\u0001");
        const g = grupos.get(k) || { ...Object.fromEntries(claves.map((c) => [c, f[c]])), veces: 0, ultima: null };
        g.veces++;
        const u = String(f.fecha_publicaci_n || "");
        if (!g.ultima || u > g.ultima) g.ultima = u;
        grupos.set(k, g);
      }
      const salida = [...grupos.values()].sort((a, b) => b.veces - a.veces || String(a.proveedor).localeCompare(String(b.proveedor)))
        .map((g) => ({ ...g, veces: String(g.veces) }));
      return res.end(JSON.stringify(salida.slice(0, parseInt(q.$limit, 10) || 1000)));
    }
    return res.end(JSON.stringify(filas.slice(0, parseInt(q.$limit, 10) || 1000)));
  };

  const cumple = (fila, clausula) => {
    /* Grupo parentizado de ORs — `(c like '%7210%' OR c like '%7211%' …)`—:
       es lo que construye lib/paa_acierto para acotar por familias de obra.
       El $where exterior se parte por « AND », así que el grupo llega entero
       (no contiene « AND ») y basta con que UNA rama cumpla. */
    if (clausula.startsWith("(") && clausula.endsWith(")") && / OR /i.test(clausula)) {
      return clausula.slice(1, -1).split(/ OR /i).some((p) => cumple(fila, p.trim()));
    }
    /* `like` con comodines a los dos lados, con o sin `upper(...)`: es lo que
       construye lib/paa para acotar por entidad y por código UNSPSC. Sin
       soportarlo, `cumple` lanzaba dentro del callback del servidor —una
       excepción no capturada que tumba el proceso de pruebas entero—, que es
       peor que un fallo de aserción. */
    const like = clausula.match(/^(?:upper\()?([^\s()]+)\)?\s+like\s+'%(.*)%'$/i);
    if (like) {
      const [, campo, aguja] = like;
      return String(fila[campo] ?? "").toUpperCase().includes(aguja.toUpperCase());
    }
    /* `starts_with(campo,'x')` — lib/socio: SIRI rellena la identificación
       con espacios y las multas pegan a veces el DV, así que se busca por
       prefijo y se confirma en el cliente. */
    const sw = clausula.match(/^starts_with\((\S+?),\s*'(.*)'\)$/i);
    if (sw) return String(fila[sw[1]] ?? "").startsWith(sw[2]);
    /* `campo in ('a','b')` genérico — lib/handlers/perfil/seguimiento cruza
       proponentes con hgi6/p6dx/jbjy por listas de NIT y estados. */
    const enLista = clausula.match(/^(\S+)\s+in\s*\((.*)\)$/i);
    if (enLista) {
      const vals = new Set(enLista[2].split(",").map((x) => x.trim().replace(/^'|'$/g, "").replace(/''/g, "'")));
      return vals.has(String(fila[enLista[1]] ?? ""));
    }
    const m = clausula.match(/^(\S+)\s*(>=|<=|>|<|=)\s*'(.*)'$/);
    if (!m) throw new Error(`mock: clausula no soportada: ${clausula}`);
    const [, campo, op, valor] = m;
    const v = String(fila[campo] ?? "");
    if (op === "=") return v === valor; // lib/ejecucion: nit_entidad='…' AND tipo_de_contrato='Obra'
    if (op === ">=") return v >= valor;
    if (op === "<=") return v <= valor;
    if (op === ">") return v > valor;
    return v < valor;
  };

  const porDataset = new Map(); // peticiones que llegaron a CADA dataset (por path), fallos inyectados incluidos
  const server = http.createServer((req, res) => {
    setTimeout(() => { // latencia simulada: fuerza el corte por presupuesto
      contadorPeticiones++;
      const ds = (req.url.match(/resource\/([a-z0-9-]+)\.json/) || [])[1] || "?";
      porDataset.set(ds, (porDataset.get(ds) || 0) + 1);
      if (inyectarFallos && contadorPeticiones % 29 === 3) {
        res.writeHead(429, { "Retry-After": "0.05" }); return res.end("rate limited");
      }
      if (inyectarFallos && contadorPeticiones % 37 === 5) {
        res.writeHead(500); return res.end("upstream error");
      }
      const u = new URL(req.url, "http://x");
      const q = Object.fromEntries(u.searchParams);
      // hgi6 con `where` = un solo `in (...)` va por la rama de proponentes; cualquier otro where, por la genérica
      if (u.pathname.includes("hgi6-6wh3") && (!q.$where || /^\s*\S+\s+in\s*\(.*\)\s*$/i.test(q.$where))) return responderProponentes(q, res);
      let filas = (u.pathname.includes("9sue-ezhx") ? datasetPaa : u.pathname.includes("jbjy-vk9h") ? datasetContratos
        : u.pathname.includes("hgi6-6wh3") ? datasetProponentes
          : u.pathname.includes("iaeu-rcn6") ? datasetSiri : u.pathname.includes("4n4q-k399") ? datasetMultas : dataset).slice();
      if (q.$where) filas = filas.filter((f) => q.$where.split(" AND ").every((c) => cumple(f, c.trim())));
      if ((q.$select || "").startsWith("count(*)")) {
        res.writeHead(200, { "Content-Type": "application/json" });
        return res.end(JSON.stringify([{ n: String(filas.length) }]));
      }
      /* `$group` genérico (lib/socio: adjudicaciones por año en p6dx). Soporta
         `expr as alias` con count(*), count(distinct f), sum(f), max(f),
         min(f) y date_trunc_y(f); agrupa por los alias/campos de $group. */
      if (q.$group) {
        const items = String(q.$select || "").split(",").map((x) => x.trim()).filter(Boolean).map((it) => {
          const mm = /^(.*?)\s+as\s+(\S+)$/i.exec(it);
          return { expr: mm ? mm[1].trim() : it, alias: mm ? mm[2] : it };
        });
        const claves = q.$group.split(",").map((x) => x.trim());
        const valorDe = (f, expr) => {
          const dt = /^date_trunc_y\((\S+)\)$/i.exec(expr);
          if (dt) { const v = String(f[dt[1]] ?? ""); return v ? `${v.slice(0, 4)}-01-01T00:00:00.000` : ""; }
          return String(f[expr] ?? "");
        };
        const exprDeAlias = Object.fromEntries(items.map((i) => [i.alias, i.expr]));
        const grupos = new Map();
        for (const f of filas) {
          const k = claves.map((c) => valorDe(f, exprDeAlias[c] || c)).join("\u0001");
          if (!grupos.has(k)) grupos.set(k, []);
          grupos.get(k).push(f);
        }
        const salida = [...grupos.values()].map((gf) => {
          const o = {};
          for (const { expr, alias } of items) {
            let mm;
            if (expr === "count(*)") o[alias] = String(gf.length);
            else if ((mm = /^count\(distinct (\S+)\)$/i.exec(expr))) o[alias] = String(new Set(gf.map((f) => f[mm[1]])).size);
            else if ((mm = /^sum\((\S+)\)$/i.exec(expr))) o[alias] = String(gf.reduce((a, f) => a + (Number(f[mm[1]]) || 0), 0));
            else if ((mm = /^max\((\S+)\)$/i.exec(expr))) o[alias] = gf.map((f) => String(f[mm[1]] ?? "")).sort().pop();
            else if ((mm = /^min\((\S+)\)$/i.exec(expr))) o[alias] = gf.map((f) => String(f[mm[1]] ?? "")).sort()[0];
            else o[alias] = valorDe(gf[0], expr);
          }
          return o;
        });
        res.writeHead(200, { "Content-Type": "application/json" });
        return res.end(JSON.stringify(salida.slice(0, parseInt(q.$limit, 10) || 1000)));
      }
      filas.sort((a, b) => (a[":id"] < b[":id"] ? -1 : 1));
      const offset = parseInt(q.$offset, 10) || 0;
      const limit = parseInt(q.$limit, 10) || 1000;
      res.writeHead(200, { "Content-Type": "application/json" });
      res.end(JSON.stringify(filas.slice(offset, offset + limit)));
    }, 15);
  });

  return {
    server,
    setDataset: (d) => { dataset = d; },
    setDatasetPaa: (d) => { datasetPaa = d; },
    setDatasetProponentes: (d) => { datasetProponentes = d; },
    setDatasetContratos: (d) => { datasetContratos = d; },
    setDatasetSiri: (d) => { datasetSiri = d; },
    setDatasetMultas: (d) => { datasetMultas = d; },
    getDataset: () => dataset,
    setFallos: (v) => { inyectarFallos = v; },
    peticiones: () => contadorPeticiones,
    peticionesA: (dataset) => porDataset.get(dataset) || 0,
  };
}

/* ════════════════ mock Upstash Redis REST ════════════════ */
function crearMockUpstash() {
  const datos = new Map();   // clave → valor
  const hashes = new Map();  // clave → Map(campo → valor)  (índice de competencia)
  const expiras = new Map(); // clave → ts de expiración
  const viva = (k) => {
    if (expiras.has(k) && Date.now() > expiras.get(k)) { datos.delete(k); expiras.delete(k); }
    return datos.has(k);
  };
  const globRe = (p) => new RegExp("^" + p.replace(/[.+^${}()|[\]\\]/g, "\\$&").replace(/\*/g, ".*") + "$");

  function ejecutar(cmd) {
    const op = String(cmd[0]).toUpperCase();
    switch (op) {
      case "GET": return viva(cmd[1]) ? datos.get(cmd[1]) : null;
      case "SET": {
        const [, k, v, ...resto] = cmd;
        const nx = resto.map((x) => String(x).toUpperCase()).includes("NX");
        if (nx && viva(k)) return null;
        datos.set(k, String(v));
        const iEx = resto.map((x) => String(x).toUpperCase()).indexOf("EX");
        if (iEx >= 0) expiras.set(k, Date.now() + parseInt(resto[iEx + 1], 10) * 1000);
        else expiras.delete(k);
        return "OK";
      }
      case "DEL": {
        let borradas = 0;
        for (const k of cmd.slice(1)) {
          if (viva(k) || hashes.has(k)) borradas++;
          datos.delete(k); expiras.delete(k); hashes.delete(k);
        }
        return borradas;
      }
      case "MGET": return cmd.slice(1).map((k) => (viva(k) ? datos.get(k) : null));
      case "TTL": {
        const k = cmd[1];
        if (!viva(k) && !hashes.has(k)) return -2;          // no existe
        if (!expiras.has(k)) return -1;                      // sin expiración
        return Math.max(0, Math.ceil((expiras.get(k) - Date.now()) / 1000));
      }
      case "EXISTS": return viva(cmd[1]) || hashes.has(cmd[1]) ? 1 : 0;
      /* EXPIRE: la única vía para poner TTL a un hash ya escrito (apu:precios:{rup_…}) */
      case "EXPIRE": {
        const k = cmd[1];
        if (!viva(k) && !hashes.has(k)) return 0;
        expiras.set(k, Date.now() + parseInt(cmd[2], 10) * 1000);
        return 1;
      }
      case "SCAN": {
        const iMatch = cmd.map((x) => String(x).toUpperCase()).indexOf("MATCH");
        const re = globRe(cmd[iMatch + 1]);
        const claves = [...datos.keys()].filter((k) => viva(k) && re.test(k))
          .concat([...hashes.keys()].filter((k) => re.test(k)));
        return ["0", claves];
      }
      /* ---- hashes: el índice de competencia por entidad ---- */
      case "HSET": {
        const [, k, ...resto] = cmd;
        const h = hashes.get(k) || new Map();
        for (let i = 0; i + 1 < resto.length; i += 2) h.set(String(resto[i]), String(resto[i + 1]));
        hashes.set(k, h);
        return Math.floor(resto.length / 2);
      }
      case "HGETALL": {
        const h = hashes.get(cmd[1]);
        if (!h) return [];
        const plano = [];
        for (const [f, v] of h) plano.push(f, v);
        return plano; // Upstash devuelve el array plano [campo, valor, …]
      }
      case "HGET": {
        const h = hashes.get(cmd[1]);
        return h && h.has(cmd[2]) ? h.get(cmd[2]) : null;
      }
      case "HLEN": return hashes.has(cmd[1]) ? hashes.get(cmd[1]).size : 0;
      case "RENAME": {
        const [, de, a] = cmd;
        if (hashes.has(de)) { hashes.set(a, hashes.get(de)); hashes.delete(de); return "OK"; }
        if (viva(de)) { datos.set(a, datos.get(de)); datos.delete(de); expiras.delete(de); return "OK"; }
        throw new Error("ERR no such key"); // como Redis: RENAME de clave inexistente falla
      }
      default: throw new Error(`mock redis: comando no soportado ${op}`);
    }
  }

  let contadorPeticiones = 0; // comandos recibidos: op=salud tiene que gastar ≤ 2 por latido
  const server = http.createServer((req, res) => {
    let cuerpo = "";
    req.on("data", (c) => { cuerpo += c; });
    req.on("end", () => {
      contadorPeticiones++;
      try {
        const r = ejecutar(JSON.parse(cuerpo));
        res.writeHead(200, { "Content-Type": "application/json" });
        res.end(JSON.stringify({ result: r }));
      } catch (e) {
        res.writeHead(400, { "Content-Type": "application/json" });
        res.end(JSON.stringify({ error: String(e.message) }));
      }
    });
  });
  return { server, tamano: () => datos.size + hashes.size, peticiones: () => contadorPeticiones };
}

/* ════════════════ invocador de handlers estilo Vercel ════════════════
   `cabeceras` se recoge de verdad (no se tira): /api/resumen anuncia por
   `X-Cache` si sirvió de la caché, y sin capturarla no habría forma de
   distinguir un HIT de un MISS desde la prueba.
   `opciones.metodo` + `opciones.body` cubren el POST de /api/admin/rup;
   Vercel entrega el cuerpo ya parseado cuando el Content-Type es JSON, y el
   handler acepta además cadena y stream (se prueban las tres formas). */
function invocar(handler, urlStr, headers = {}, opciones = {}) {
  const u = new URL(urlStr, "http://app.local");
  const req = {
    url: urlStr, method: opciones.metodo || "GET",
    headers: { host: "app.local", "x-forwarded-proto": "https", ...headers },
    query: Object.fromEntries(u.searchParams),
  };
  if (opciones.body !== undefined) req.body = opciones.body;
  return new Promise((resolve, reject) => {
    const cabeceras = {};
    const res = {
      _status: 200,
      setHeader(k, v) { cabeceras[String(k).toLowerCase()] = String(v); },
      status(n) { this._status = n; return this; },
      json(o) { resolve({ status: this._status, cuerpo: o, cabeceras }); },
      send(b) { resolve({ status: this._status, cuerpo: b, cabeceras }); },
      end() { resolve({ status: this._status, cuerpo: null, cabeceras }); },
    };
    Promise.resolve(handler(req, res)).catch(reject);
  });
}
const invocarPost = (handler, urlStr, body, headers = {}) =>
  invocar(handler, urlStr, { "content-type": "application/json", ...headers }, { metodo: "POST", body });

const escuchar = (server) => new Promise((r) => server.listen(0, "127.0.0.1", () => r(server.address().port)));

/* Quita comentarios de un fuente antes de vigilarlo con expresiones regulares:
   varios comentarios CITAN a propósito el código defectuoso que explican, y una
   aserción que no los distinga acaba fallando por la explicación del arreglo. */
const sinComentarios = (fuente) => String(fuente)
  .replace(/\/\*[\s\S]*?\*\//g, "")
  .replace(/^\s*\/\/.*$/gm, "");

/* Todas las HOJAS de texto de una respuesta JSON (6-sep-2026): sirve para censar lo
   que el servidor DEVUELVE —una alerta, un badge, un aviso— y no solo su fuente, que
   es donde un pictograma llega a la pantalla sin que la cerca de public/*.js lo vea. */
const textosDe = (v, out = []) => {
  if (typeof v === "string") out.push(v);
  else if (Array.isArray(v)) v.forEach((x) => textosDe(x, out));
  else if (v && typeof v === "object") Object.values(v).forEach((x) => textosDe(x, out));
  return out;
};

